Shader.VertexShader:
in vec3 a_position; in vec2 a_texcoord0; in vec2 a_texcoord1; in vec4 a_color;
out vec2 v_uv0; out vec2 v_uv1; out vec3 v_tint;
uniform mat4 u_modelViewProjectionTransform;
void main() {
  v_uv0 = a_texcoord0; v_uv1 = a_texcoord1;
  v_tint = pow(a_color.rgb, vec3(2.2));
  gl_Position = u_modelViewProjectionTransform * vec4(a_position, 1.0);
}

Shader.FragmentShader:
in vec2 v_uv0; in vec2 v_uv1; in vec3 v_tint;
vec3 clothLevel(float level, float spine) {
  float scale = exp2(-level);
  vec2 uv = vec2(v_uv0.x, v_uv0.y * 0.5) * scale;
  // Clamp within this book's strip at both levels, even when just one texel wide.
  vec2 halfTexel = vec2(0.5 / 256.0);
  uv = clamp(uv, vec2(spine / 8.0, 0.0) * scale + halfTexel,
                  vec2((spine + 1.0) / 8.0, 0.5) * scale - halfTexel);
  return texture(Albedo, uv + vec2(0.0, 1.0 - scale)).rgb;
}
void main() {
  vec3 light = texture(Lightmap, v_uv1).rgb * 4.0;   // the bake's LIGHTMAP_RANGE
  vec3 albedo;
  if (ClothAtlas > 0.5) {
    vec2 texel = v_uv0 * vec2(256.0, 128.0);
    float lod = clamp(log2(max(max(length(dFdx(texel)), length(dFdy(texel))), 1.0)), 0.0, 5.0);
    float spine = floor(v_uv0.x * 8.0);
    albedo = mix(clothLevel(floor(lod), spine), clothLevel(ceil(lod), spine), fract(lod));
  } else {
    albedo = texture(Albedo, fract(v_uv0)).rgb;
  }
  vec3 c = albedo * v_tint * light;
  c = c / (1.0 + 0.45 * c);          // soft shoulder so the lamp's pool keeps its colour
  FragColor = vec4(c * 1.3, 1.0);
}

Shader.VertexShader:
#include <metal_stdlib>
using namespace metal;
struct Uniforms { float4x4 u_modelViewProjectionTransform; float orca_FlipY; };
struct VertexIn {
  float3 a_position [[attribute(0)]]; float2 a_texcoord0 [[attribute(1)]];
  float2 a_texcoord1 [[attribute(2)]]; float4 a_color [[attribute(3)]];
};
struct VertexOut { float4 position [[position]]; float2 v_uv0; float2 v_uv1; float3 v_tint; };
vertex VertexOut vertexStage(VertexIn in [[stage_in]], constant Uniforms& u [[buffer(0)]]) {
  VertexOut out;
  out.v_uv0 = in.a_texcoord0; out.v_uv1 = in.a_texcoord1;
  out.v_tint = pow(in.a_color.rgb, float3(2.2));
  out.position = u.u_modelViewProjectionTransform * float4(in.a_position, 1.0);
  out.position.y *= u.orca_FlipY;                             // the target's row order
  out.position.z = (out.position.z + out.position.w) * 0.5;   // depth -1..1 to Metal's 0..1
  return out;
}

Shader.FragmentShader:
#include <metal_stdlib>
using namespace metal;
struct Uniforms { float ClothAtlas; };
struct FragmentIn { float2 v_uv0; float2 v_uv1; float3 v_tint; };
static float3 clothLevel(texture2d<float> albedo, sampler s, float2 uv0, float level, float spine) {
  float scale = exp2(-level);
  float2 uv = float2(uv0.x, uv0.y * 0.5) * scale;
  // Clamp within this book's strip at both levels, even when just one texel wide.
  float2 halfTexel = float2(0.5 / 256.0);
  uv = clamp(uv, float2(spine / 8.0, 0.0) * scale + halfTexel,
                 float2((spine + 1.0) / 8.0, 0.5) * scale - halfTexel);
  return albedo.sample(s, uv + float2(0.0, 1.0 - scale)).rgb;
}
fragment float4 fragmentStage(FragmentIn in [[stage_in]], constant Uniforms& u [[buffer(0)]],
                              texture2d<float> Albedo [[texture(0)]], sampler AlbedoSampler [[sampler(0)]],
                              texture2d<float> Lightmap [[texture(1)]], sampler LightmapSampler [[sampler(1)]]) {
  float3 light = Lightmap.sample(LightmapSampler, in.v_uv1).rgb * 4.0;   // the bake's LIGHTMAP_RANGE
  float3 albedo;
  if (u.ClothAtlas > 0.5) {
    float2 texel = in.v_uv0 * float2(256.0, 128.0);
    float lod = clamp(log2(max(max(length(dfdx(texel)), length(dfdy(texel))), 1.0)), 0.0, 5.0);
    float spine = floor(in.v_uv0.x * 8.0);
    albedo = mix(clothLevel(Albedo, AlbedoSampler, in.v_uv0, floor(lod), spine),
                 clothLevel(Albedo, AlbedoSampler, in.v_uv0, ceil(lod), spine), fract(lod));
  } else {
    albedo = Albedo.sample(AlbedoSampler, fract(in.v_uv0)).rgb;
  }
  float3 c = albedo * in.v_tint * light;
  c = c / (1.0 + 0.45 * c);          // soft shoulder so the lamp's pool keeps its colour
  return float4(c * 1.3, 1.0);
}
